#!/usr/bin/env python3
"""Compute ground truth for CSX-270_Q2 from local package JSON files."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any


TASK_ID = "CSX-270_Q2"
EVENT_ID = "CSX-270"
TARGET_FAMILY = "east_africa_multisource_rainfall_structure_ledger"
REPO_ROOT = Path(__file__).resolve().parents[3]
PACKAGE_ROOT = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
OUTPUT_PATH = Path(__file__).resolve().parent / "computed_gt.json"

EVENT_ANCHOR = (
    "data/event_reports/"
    "event_reports_003_Locked_event_anchor_2019_positive_Indian_Ocean_Dipole_and_East_Africa_floods.json"
)
PRODUCT_FILES = {
    "GPM_IMERG": "data/physical_hazard/physical_hazard_011_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "ERA5_Land": "data/physical_hazard/physical_hazard_010_ERA5-Land_hourly_aggregate_stats.json",
    "CHIRPS": "data/physical_hazard/physical_hazard_012_CHIRPS_daily_event_accumulated_precipitation.json",
}
COMPACT_AOI = "data/geospatial_context/geospatial_context_002_compact_per-event_AOI_derived_from_event_bbox.json"
POINT_SAMPLE_OPEN_METEO = "data/physical_hazard/physical_hazard_008_Open-Meteo_historical_daily_point_sample.json"
POINT_SAMPLE_POWER = "data/physical_hazard/physical_hazard_009_NASA_POWER_daily_point_sample.json"


def read_json(relative_path: str) -> dict[str, Any]:
    with (PACKAGE_ROOT / relative_path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def rounded(value: float, digits: int = 6) -> float:
    return round(float(value), digits)


def product_stats(name: str) -> tuple[str, dict[str, float]]:
    payload = read_json(PRODUCT_FILES[name])
    stats = payload["stats"]
    if name == "GPM_IMERG":
        prefix = "gpm_event_precip_mm"
    elif name == "ERA5_Land":
        prefix = "precipitation_sum_mm"
    elif name == "CHIRPS":
        prefix = "chirps_event_precip_mm"
    else:
        raise ValueError(f"Unknown product: {name}")

    mean = float(stats[f"{prefix}_mean"])
    stddev = float(stats[f"{prefix}_stdDev"])
    minimum = float(stats[f"{prefix}_min"])
    maximum = float(stats[f"{prefix}_max"])
    range_mm = maximum - minimum
    return (
        f"{payload['start']} to {payload['end']}",
        {
            "mean_mm": rounded(mean, 3),
            "stddev_mm": rounded(stddev, 3),
            "min_mm": rounded(minimum, 3),
            "max_mm": rounded(maximum, 3),
            "cv": rounded(stddev / mean),
            "peak_to_mean": rounded(maximum / mean),
            "normalized_range": rounded(range_mm / mean),
            "range_mm": rounded(range_mm, 3),
        },
    )


def rainfall_products() -> tuple[str, dict[str, dict[str, float]]]:
    products: dict[str, dict[str, float]] = {}
    windows = set()
    for name in ("GPM_IMERG", "ERA5_Land", "CHIRPS"):
        window, stats = product_stats(name)
        windows.add(window)
        products[name] = stats
    if len(windows) != 1:
        raise ValueError(f"Product windows differ: {sorted(windows)}")
    return windows.pop(), products


def compact_aoi_bounds() -> dict[str, float]:
    coords = read_json(COMPACT_AOI)["geometry"]["coordinates"][0]
    lon_values = [point[0] for point in coords]
    lat_values = [point[1] for point in coords]
    return {
        "min_lon": min(lon_values),
        "max_lon": max(lon_values),
        "min_lat": min(lat_values),
        "max_lat": max(lat_values),
    }


def point_inside(bounds: dict[str, float], lon: float, lat: float) -> bool:
    return bounds["min_lon"] <= lon <= bounds["max_lon"] and bounds["min_lat"] <= lat <= bounds["max_lat"]


def max_run(values: list[float], threshold: float) -> int:
    best = 0
    current = 0
    for value in values:
        if value >= threshold:
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best


def point_samples(bounds: dict[str, float]) -> dict[str, dict[str, Any]]:
    open_meteo = read_json(POINT_SAMPLE_OPEN_METEO)
    power = read_json(POINT_SAMPLE_POWER)
    open_values = [float(value) for value in open_meteo["daily"]["precipitation_sum"]]
    power_values = [float(value) for value in power["properties"]["parameter"]["PRECTOTCORR"].values()]
    samples = {
        "Open_Meteo": {
            "lat": rounded(open_meteo["latitude"], 6),
            "lon": rounded(open_meteo["longitude"], 6),
            "total_mm": rounded(sum(open_values), 3),
            "wet_days_ge_1mm": sum(1 for value in open_values if value >= 1.0),
            "max_wet_run_ge_1mm": max_run(open_values, 1.0),
        },
        "NASA_POWER": {
            "lat": rounded(power["geometry"]["coordinates"][1], 6),
            "lon": rounded(power["geometry"]["coordinates"][0], 6),
            "total_mm": rounded(sum(power_values), 3),
            "wet_days_ge_1mm": sum(1 for value in power_values if value >= 1.0),
            "max_wet_run_ge_1mm": max_run(power_values, 1.0),
        },
    }
    for sample in samples.values():
        sample["inside_compact_aoi"] = point_inside(bounds, sample["lon"], sample["lat"])
    return samples


def scoring(products: dict[str, dict[str, float]], inside_point_samples: int) -> dict[str, int]:
    cv_order = sorted(products, key=lambda name: products[name]["cv"], reverse=True)
    return {
        "mean_ge_280_count": sum(1 for values in products.values() if values["mean_mm"] >= 280.0),
        "cv_ge_0_10_count": sum(1 for values in products.values() if values["cv"] >= 0.10),
        "cv_order_pass": int(cv_order == ["GPM_IMERG", "ERA5_Land", "CHIRPS"]),
        "chirps_smoother_pass": int(
            products["CHIRPS"]["cv"] < 0.06
            and products["GPM_IMERG"]["cv"] >= 0.10
            and products["ERA5_Land"]["cv"] >= 0.10
        ),
        "inside_point_samples": inside_point_samples,
    }


def rubric() -> dict[str, Any]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Structured product extraction",
                "points": 4,
                "description": "Extracts mean, standard deviation, minimum, and maximum from all three gridded rainfall JSON summaries with units preserved.",
                "partial_credit": "Award 2-3 points if two products are complete or one field is missing across products.",
            },
            {
                "name": "Derived rainfall ratios",
                "points": 4,
                "description": "Computes CV, peak-to-mean, and normalized range for each product within tolerance.",
                "partial_credit": "Award 2-3 points for correct formulas with one product or rounding error.",
            },
            {
                "name": "Threshold ledger arithmetic",
                "points": 4,
                "description": "Computes the four score components and final score of 7 from the stated formula.",
                "partial_credit": "Award 1 point for each correctly computed score component.",
            },
            {
                "name": "Point-sample/AOI overlap diagnostic",
                "points": 3,
                "description": "Reports point-sample/AOI overlap as a package diagnostic and keeps it out of the rainfall-structure score.",
                "partial_credit": "Award 1-2 points for reporting the overlap result but not clearly stating its diagnostic-only role.",
            },
            {
                "name": "Source ranking and strongest signal",
                "points": 3,
                "description": "Reports CV order as GPM_IMERG, ERA5_Land, CHIRPS and identifies GPM_IMERG as the highest peak-to-mean product.",
                "partial_credit": "Award 1-2 points if either the CV order or strongest peak-to-mean product is correct.",
            },
            {
                "name": "Compact numeric JSON",
                "points": 2,
                "description": "Returns the requested compact JSON with numeric anchors, ledger counts, score, and final label.",
                "partial_credit": "Award 1 point for valid compact JSON with one missing requested field.",
            },
        ],
    }


def main() -> None:
    anchor = read_json(EVENT_ANCHOR)
    rainfall_window, products = rainfall_products()
    cv_order = sorted(products, key=lambda name: products[name]["cv"], reverse=True)
    strongest_product = max(products, key=lambda name: products[name]["peak_to_mean"])
    bounds = compact_aoi_bounds()
    samples = point_samples(bounds)
    inside_point_samples = sum(1 for sample in samples.values() if sample["inside_compact_aoi"])
    ledger = scoring(products, inside_point_samples)
    score = (
        ledger["mean_ge_280_count"]
        + ledger["cv_ge_0_10_count"]
        + ledger["cv_order_pass"]
        + ledger["chirps_smoother_pass"]
    )
    final_label = f"localized_gridded_rainfall_structure_score_{score}"
    sampling_scope = (
        "Point-sample/AOI overlap is reported as a package diagnostic only; it is not part of the score "
        "and is not used to judge event-location validity."
    )

    computed = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "primary_gt": {
            "target_family": TARGET_FAMILY,
            "score": score,
            "cv_order": cv_order,
            "strongest_peak_to_mean_product": strongest_product,
            "product_metrics": products,
            "ledger": ledger,
            "inside_point_samples": inside_point_samples,
            "sampling_scope": sampling_scope,
            "final_label": final_label,
        },
        "event": {
            "package_id": EVENT_ID,
            "event_name": anchor["event_name"],
            "hazard_family": anchor["hazard_family"],
            "event_date_or_window": f"{anchor['temporal_window']['start_date']} to {anchor['temporal_window']['end_date']}",
        },
        "calculation_rule": {
            "rainfall_window": rainfall_window,
            "formula": "score = mean_ge_280_count + cv_ge_0_10_count + cv_order_pass + chirps_smoother_pass",
            "thresholds": {
                "mean_mm": 280.0,
                "cv_structured": 0.10,
                "chirps_smooth_cv": 0.06,
                "point_wet_day_mm": 1.0,
            },
            "numeric_tolerances": {
                "mm": 0.01,
                "ratio": 0.0005,
                "score": 0,
            },
        },
        "key_values": {
            "products": products,
            "cv_order_high_to_low": cv_order,
            "strongest_peak_to_mean_product": strongest_product,
            "compact_aoi_bounds": bounds,
            "point_samples": samples,
            "sampling_scope": sampling_scope,
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                EVENT_ANCHOR,
                PRODUCT_FILES["GPM_IMERG"],
                PRODUCT_FILES["ERA5_Land"],
                PRODUCT_FILES["CHIRPS"],
                COMPACT_AOI,
                POINT_SAMPLE_OPEN_METEO,
                POINT_SAMPLE_POWER,
            ],
        },
        "rubric": rubric(),
    }
    OUTPUT_PATH.write_text(json.dumps(computed, indent=2, ensure_ascii=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
